 private FinanceAccountingModels.Line line(String account,BigDecimal debit,BigDecimal credit,String text){return new FinanceAccountingModels.Line(account,money(debit),money(credit),text,null);}
 private void accountCategory(TenantPrincipal p,UUID book,String code,String category){one("select id from fa_account where tenant_id=:tenant and book_id=:book and code=:code and category=:category and enabled and not cash_account",base(p).addValue("book",book).addValue("code",code).addValue("category",category));}
 private void validateReceiptDimensions(TenantPrincipal p,Map<String,Object> recognition){
  if(!FinanceCostDimensions.procurementSwitchInstalled(jdbc))return;
  UUID hotel=id(recognition,"hotel_id");
  var lines=jdbc.queryForList("select l.line_kind,coalesce(l.financial_category_code,c.financial_category_code) code,coalesce(l.financial_department_id,c.financial_department_id) department,case when l.project_kind<>'NONE' then l.project_kind else coalesce(c.project_kind,l.project_kind) end project_kind,case when l.project_kind<>'NONE' then l.project_id else coalesce(c.project_id,l.project_id) end project_id from procurement_receipt_line r join procurement_line l on l.tenant_id=r.tenant_id and l.id=r.line_id left join fs_procurement_finance_classification c on c.tenant_id=l.tenant_id and c.line_id=l.id where r.tenant_id=:tenant and r.receipt_id=:receipt and r.accepted>0",base(p).addValue("receipt",recognition.get("receipt_id")));
  if(lines.isEmpty())throw fail("原复核批次没有可核算的实际验收行");
  for(var line:lines){String kind=str(line,"line_kind");Set<String> treatments=kind.equals("SERVICE")?Set.of("EXPENSE"):Set.of("ASSET","PROJECT").contains(kind)?Set.of("ASSET"):Set.of("EXPENSE","INVENTORY");
   FinanceCostDimensions.validate(jdbc,p.tenantId(),hotel,str(line,"code"),id(line,"department"),treatments);
   FinanceCostDimensions.freezeProject(jdbc,p,hotel,str(line,"project_kind"),id(line,"project_id"));
  }
 }
 private void requireAccountingPeriod(TenantPrincipal p,UUID hotel,LocalDate date){var books=jdbc.queryForList("select b.id,b.start_month,p.status from fa_book b left join fa_period p on p.tenant_id=b.tenant_id and p.book_id=b.id and p.month=:month where b.tenant_id=:tenant and b.hotel_id=:hotel and b.enabled",base(p).addValue("hotel",hotel).addValue("month",date.withDayOfMonth(1)));for(var book:books)if(date.isBefore(date(book,"start_month"))||book.get("status")!=null&&!"OPEN".equals(book.get("status")))throw fail("所选核算期间已关账或早于账套切换，请以当前开放期登记真实调整，不改写旧期");}
